import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() - days);
  return date;
};

const presets = [
  { key: 'today', label: 'Сегодня', days: 0 },
  { key: 'yesterday', label: 'Вчера', days: 1 },
  { key: 'week', label: 'Неделя назад', days: 7 },
];

export default function ReportDatePicker({ value, onChange, locale = 'ru-RU' }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(value ?? null);
  const selected = value !== undefined ? value : internalDate;

  const select = (next: Date | null) => {
    if (value === undefined) setInternalDate(next);
    onChange?.(next);
  };

  const isSameDay = (a: Date | null, b: Date) =>
    a != null && startOfDay(a).getTime() === b.getTime();

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.days);
          const active = isSameDay(selected, presetDate);
          return (
            <JxChip
              key={preset.key}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              active={active}
              onClick={() => select(presetDate)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  select(presetDate);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar
        locale={locale}
        value={selected}
        onValueChange={(next) => select(next ? startOfDay(next) : null)}
      />

      <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)', fontSize: '13px' }}>
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString(locale, { day: 'numeric', month: 'long', year: 'numeric' })}`
          : 'Дата не выбрана — выберите день в календаре или быстрый вариант выше.'}
      </span>
    </div>
  );
}

